import glob, re, os, xml.etree.ElementTree as ET
ns={'c':'http://schemas.openxmlformats.org/drawingml/2006/chart'}
files=sorted(glob.glob('/tmp/xlsx_extract/xl/charts/chart*.xml'), key=lambda x:int(re.search(r'chart(\d+)\.xml',x).group(1)))
for f in files:
    try:
        root=ET.parse(f).getroot()
    except Exception as e:
        print('ERR',f,e); continue
    # get all c:ser
    sers=root.findall('.//c:ser',ns)
    print(os.path.basename(f), 'series', len(sers))
    for ser in sers[:3]:
        # formula refs
        refs=[]
        for tag in ['c:tx','c:cat','c:val']:
            e=ser.find(tag,ns)
            if e is not None:
                fr=e.find('.//c:f',ns)
                if fr is not None:
                    refs.append(f'{tag}:{fr.text}')
        print('  ', refs)
